    value: "vue",
    icon: "🟩",
    group: "UI libraries",
    description: "Progressive framework",
  },
  {
    label: "Lit",
    value: "lit",
    icon: "🔥",
    group: "UI libraries",
    description: "Web Components base class",
  },
  {
    label: "Next.js",
